head.script:
scwin.btn_trigger1_onclick = function() {
    tabControl1.addTab("cmcm011" + n++, {
        "label": "공통코드등록",
        "title": "공통코드등록",
        "openAction": "new",
        "closable": "true"
    }, {
        "src": "tabControl_tabPosition_WPFF-255_(WSQ-3579)_sub.xml",
        "wframe": true,
        "scope": true,
        "alwaysDraw": "true"
    });
};
scwin._checkErr = function() {
    var log = WebSquare.logger.getLog();
    return log.indexOf("Cannot read property 'setValue' of null") == -1;
}
scwin.checkLog = function() {
    return WebSquare.logger.getErrorLog();
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('btn_trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin._checkErr()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkLog() == ''", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();

scwin.onpageload = function() {
    window.n = 0;
    tabControl1.addTab("cmcm011" + n++, {
        "label": "공통코드등록",
        "title": "공통코드등록",
        "openAction": "new",
        "closable": "true"
    }, {
        "src": "tabControl_tabPosition_WPFF-255_(WSQ-3579)_sub.xml",
        "wframe": true,
        "scope": true,
        "alwaysDraw": "true"
    });
}
